from pathlib import Path
import json,collections

def analyze(path):
 rows=json.loads(Path(path).read_text());total=sum(r['samples'] for r in rows)
 hist=collections.Counter();starts=collections.Counter();edges=collections.Counter()
 for r in rows:
  n=r['samples'];hist[r['instructions']]+=n
  a=(r['cr3'],r['base'],r['cs'],r['ip']);b=(*a[:3],r['target']);starts[a]+=n;edges[a,b]+=n
 hot=[(a,b,n) for (a,b),n in edges.items() if n>=total*.005]
 nodes={a for a,b,n in hot}|{b for a,b,n in hot};g={a:[] for a in nodes};rg={a:[] for a in nodes}
 for a,b,n in hot:g[a].append(b);rg[b].append(a)
 seen=set();order=[]
 def visit(a):
  if a in seen:return
  seen.add(a)
  for b in g[a]:visit(b)
  order.append(a)
 for a in nodes:visit(a)
 seen.clear();components=[]
 def collect(a,c):
  if a in seen:return
  seen.add(a);c.add(a)
  for b in rg[a]:collect(b,c)
 for a in reversed(order):
  if a not in seen:c=set();collect(a,c);components.append(c)
 comps=sorted([{'nodes':len(c),'internalSamples':sum(n for a,b,n in hot if a in c and b in c),'addresses':[list(a) for a in sorted(c)]} for c in components],key=lambda c:c['internalSamples'],reverse=True)
 return {'rows':len(rows),'samples':total,'selfLoopPercent':100*sum(n for (a,b),n in edges.items() if a==b)/total,'registerOnlySelfLoopPercent':100*sum(r['samples'] for r in rows if r['ip']==r['target'] and not r['memoryOps'] and 2<=r['instructions']<=32)/total,'instructionHistogram':dict(sorted(hist.items())),'oneToFiveInstructionPercent':100*sum(n for k,n in hist.items() if 1<=k<=5)/total,'memoryBlockPercent':100*sum(r['samples'] for r in rows if r['memoryOps'])/total,'top40StartPercent':100*sum(n for _,n in starts.most_common(40))/total,'topStarts':[{'location':list(a),'samples':n,'percent':100*n/total} for a,n in starts.most_common(40)],'hotEdgeThresholdPercent':.5,'hotEdges':len(hot),'hotComponents':comps,'topEdges':sorted(rows,key=lambda r:r['samples'],reverse=True)[:40]}
if __name__=='__main__':
 import sys
 r=analyze(sys.argv[1]);Path(sys.argv[2]).write_text(json.dumps(r,indent=2)+'\n');print({k:r[k] for k in ['samples','selfLoopPercent','registerOnlySelfLoopPercent','oneToFiveInstructionPercent','memoryBlockPercent','top40StartPercent','hotEdges']});print('components',[(x['nodes'],x['internalSamples']/r['samples']*100) for x in r['hotComponents'][:4]])
